void ips130_show_image (uint8 image_index)
{
    uint32 i = 0;
    const uint16 *image_temp;

    IPS130_CS(0);
    ips130_set_region(0, 0, 239, 239);

    for(i = 0; i < 240; i ++)
    {
        if(image_index == 0)
            image_temp = ips130_image_data + i * 240;
        else
            image_temp = ips130_image2_data + i * 240;
        ips130_write_8bit_data_array((uint8 *)image_temp, 240 * 2);
    }
    IPS130_CS(1);
}

//-------------------------------------------------------------------------------------------------------------------
// 函数简介     1.30寸 IPS液晶初始化 (ST7789 240x240)
// 参数说明     void
// 返回参数     void
// 使用示例     ips130_init();
// 备注信息
//-------------------------------------------------------------------------------------------------------------------
void ips130_init (void)
{
#if IPS130_USE_SOFT_SPI
    soft_spi_init(&ips130_spi, 0, IPS130_SOFT_SPI_DELAY, IPS130_SCL_PIN, IPS130_SDA_PIN, SOFT_SPI_PIN_NULL, SOFT_SPI_PIN_NULL);
#else
    spi_init(IPS130_SPI, SPI_MODE0, IPS130_SPI_SPEED, IPS130_SCL_PIN, IPS130_SDA_PIN, IPS130_SDA_IN_PIN, SPI_CS_NULL);
#endif

    gpio_init(IPS130_DC_PIN, GPO, GPIO_LOW, GPO_PUSH_PULL);
    gpio_init(IPS130_RST_PIN, GPO, GPIO_LOW, GPO_PUSH_PULL);
    gpio_init(IPS130_CS_PIN, GPO, GPIO_HIGH, GPO_PUSH_PULL);
    gpio_init(IPS130_BLK_PIN, GPO, GPIO_HIGH, GPO_PUSH_PULL);

    ips130_set_dir(ips130_display_dir);
    ips130_set_color(ips130_pencolor, ips130_bgcolor);

    IPS130_RST(0);
    system_delay_ms(5);

    IPS130_RST(1);
    system_delay_ms(120);

    IPS130_CS(0);
    ips130_write_index(0x11);
    system_delay_ms(120);                                                       // 1.30寸屏幕需要额外延时

    ips130_write_index(0x36);
    switch(ips130_display_dir)
    {
        case IPS130_PORTAIT:        ips130_write_8bit_data(0xA0);   break;
        case IPS130_PORTAIT_180:    ips130_write_8bit_data(0x70);   break;
        case IPS130_CROSSWISE:      ips130_write_8bit_data(0x00);   break;
        case IPS130_CROSSWISE_180:  ips130_write_8bit_data(0xC0);   break;
    }

    ips130_write_index(0x3A);
    ips130_write_8bit_data(0x05);

    ips130_write_index(0xB2);
    ips130_write_8bit_data(0x0C);
    ips130_write_8bit_data(0x0C);
    ips130_write_8bit_data(0x00);
    ips130_write_8bit_data(0x33);
    ips130_write_8bit_data(0x33);

    ips130_write_index(0xB7);
    ips130_write_8bit_data(0x35);

    ips130_write_index(0xBB);
    ips130_write_8bit_data(0x19);                                               // 1.30寸屏幕参数调整

    ips130_write_index(0xC0);
    ips130_write_8bit_data(0x2C);

    ips130_write_index(0xC2);
    ips130_write_8bit_data(0x01);

    ips130_write_index(0xC3);
    ips130_write_8bit_data(0x12);

    ips130_write_index(0xC4);
    ips130_write_8bit_data(0x20);

    ips130_write_index(0xC6);
    ips130_write_8bit_data(0x0F);

    ips130_write_index(0xD0);
    ips130_write_8bit_data(0xA4);
    ips130_write_8bit_data(0xA1);

    ips130_write_index(0xE0);
    ips130_write_8bit_data(0xD0);
    ips130_write_8bit_data(0x04);
    ips130_write_8bit_data(0x0D);
    ips130_write_8bit_data(0x11);
    ips130_write_8bit_data(0x13);
    ips130_write_8bit_data(0x2B);
    ips130_write_8bit_data(0x3F);
    ips130_write_8bit_data(0x54);
    ips130_write_8bit_data(0x4C);
    ips130_write_8bit_data(0x18);
    ips130_write_8bit_data(0x0D);
    ips130_write_8bit_data(0x0B);
    ips130_write_8bit_data(0x1F);
    ips130_write_8bit_data(0x23);

    ips130_write_index(0xE1);
    ips130_write_8bit_data(0xD0);
    ips130_write_8bit_data(0x04);
    ips130_write_8bit_data(0x0C);
    ips130_write_8bit_data(0x11);
    ips130_write_8bit_data(0x13);
    ips130_write_8bit_data(0x2C);
    ips130_write_8bit_data(0x3F);
    ips130_write_8bit_data(0x44);
    ips130_write_8bit_data(0x51);
    ips130_write_8bit_data(0x2F);
    ips130_write_8bit_data(0x1F);
    ips130_write_8bit_data(0x1F);
    ips130_write_8bit_data(0x20);
    ips130_write_8bit_data(0x23);

    ips130_write_index(0x21);

    ips130_write_index(0x29);
    IPS130_CS(1);

    ips130_clear();
    ips130_debug_init();
}
